import androidx.compose.ui.graphics.ColorFilter
import androidx.compose.ui.platform.LocalContext
import androidx.compose.ui.res.painterResource
import androidx.compose.ui.text.font.FontWeight
import androidx.compose.ui.text.style.TextAlign
import androidx.compose.ui.unit.dp
import androidx.compose.ui.unit.sp
import androidx.lifecycle.viewmodel.compose.viewModel
import com.hoaiphong.composeui.R

@Composable
fun PlaylistScreen(
 modifier: Modifier = Modifier,
 viewModel: PlayListViewModel = viewModel()
) {
 val context = LocalContext.current
 val state by viewModel.state.collectAsState()

 var newPlaylistName by rememberSaveable { mutableStateOf("") }

 Box(
 modifier = modifier
 .background(Color(0xFF121212))
 .fillMaxSize()
 ) {
 Column {
 Spacer(modifier = Modifier.height(32.dp))

 // Header
 Box(
 modifier = Modifier
 .fillMaxWidth()
 .padding(horizontal = 14.dp)
 ) {
 Text(
 text = "My Playlist",
 fontSize = 25.sp,
 color = Color.White,
 textAlign = TextAlign.Center,
 modifier = Modifier.align(Alignment.Center)
 )

 Row(
 modifier = Modifier.align(Alignment.CenterEnd),
 verticalAlignment = Alignment.CenterVertically
 ) {
 Image(
 painter = painterResource(id = R.drawable.ic_add),
 contentDescription = "Add Playlist",
 colorFilter = ColorFilter.tint(Color.White),
 modifier = Modifier
 .size(25.dp)
 .clickable {
 viewModel.dispatch(PlaylistIntent.ShowAddPlaylistDialog)
 }
 )
 }
 }

 Spacer(modifier = Modifier.height(16.dp))

 if (state.playlists.isEmpty()) {
 Box(
 modifier = Modifier
 .fillMaxSize(),
 contentAlignment = Alignment.Center
 ) {
 Column(horizontalAlignment = Alignment.CenterHorizontally) {
 Text(
 text = "Choose playlist",
 fontSize = 20.sp,
 fontWeight = FontWeight.Bold,
 color = Color.White,
 textAlign = TextAlign.Center
 )

 Spacer(modifier = Modifier.height(32.dp))

 Text(
 text = "You don't have any \nplaylists. Click the \n“+” button to add",
 fontSize = 16.sp,
 color = Color.White,
 textAlign = TextAlign.Center
 )

 Spacer(modifier = Modifier.height(24.dp))

 IconButton(
 onClick = {
 viewModel.dispatch(PlaylistIntent.ShowAddPlaylistDialog)
 },
 modifier = Modifier
 .size(48.dp)
 .background(Color.Transparent, shape = RoundedCornerShape(12.dp))
 .border(1.dp, Color.White, shape = RoundedCornerShape(12.dp))
 ) {
 Icon(
 imageVector = Icons.Default.Add,
 contentDescription = "Add playlist",
 tint = Color.White
 )
 }
 }
 }
 } else {
 LazyColumn(
 contentPadding = PaddingValues(16.dp),
 verticalArrangement = Arrangement.spacedBy(12.dp)
 ) {
 items(state.playlists.size) { index ->
 val playlist = state.playlists[index]
 PlaylistItem(
 playlist = playlist,
 onRemoveClick = {
 viewModel.dispatch(PlaylistIntent.RemovePlaylist(playlist.name))
 },
 onRename = { oldName, newName ->
 viewModel.dispatch(PlaylistIntent.RenamePlaylist(oldName, newName))
 }
 )
 }
 }
 }
 }

 if (state.showAddDialog) {
 AlertDialog(
 onDismissRequest = {
 viewModel.dispatch(PlaylistIntent.DismissAddPlaylistDialog)
 newPlaylistName = ""
 },
 title = {
 Text(text = "New Playlist")
 },
 text = {
 OutlinedTextField(
 value = newPlaylistName,
 onValueChange = { newPlaylistName = it },
 label = { Text("Enter name") }
 )
 },
 confirmButton = {
 Button(
 onClick = {
 viewModel.dispatch(PlaylistIntent.AddPlaylist(newPlaylistName))
 newPlaylistName = ""
 }
 ) {
 Text("Add")
 }
 },
 dismissButton = {
 Button(
 onClick = {
 viewModel.dispatch(PlaylistIntent.DismissAddPlaylistDialog)
 newPlaylistName = ""
 }
 ) {
 Text("Cancel")
 }
 }
 )
 }
 }
}
